package dev.eugheist.ttmodern;
final class AwakenedPickAudit {
 static void check(boolean ok,String label){if(!ok)throw new IllegalStateException("TT awakened pick: "+label);}
 static void run(net.minecraft.server.MinecraftServer server){var level=server.overworld();var p=new net.neoforged.neoforge.common.util.FakePlayer(level,new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"PickAudit"));p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);var stack=new net.minecraft.world.item.ItemStack(AwakenedPick.ITEM.get());p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,stack);var origin=new net.minecraft.core.BlockPos(5,290,5);p.setPos(5.5,292,5.5);p.setXRot(90);p.setYRot(0);var positions=new java.util.HashSet<>(AdvancedToolModes.pick(1,net.minecraft.core.Direction.UP).positions(origin));positions.addAll(AdvancedToolModes.pick(2,net.minecraft.core.Direction.UP).positions(origin));positions.add(origin);var saved=new java.util.HashMap<net.minecraft.core.BlockPos,net.minecraft.world.level.block.state.BlockState>();positions.forEach(at->saved.put(at,level.getBlockState(at)));
 try{for(int mode=0;mode<3;mode++){positions.forEach(at->level.setBlock(at,net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),2));check(p.gameMode.destroyBlock(origin),"real center break "+mode);long count=positions.stream().filter(at->level.getBlockState(at).isAir()).count();check(count==new int[]{1,25,11}[mode],"native selected mode exact break count "+mode+"="+count);p.setShiftKeyDown(true);AwakenedPick.ITEM.get().use(level,p,net.minecraft.world.InteractionHand.MAIN_HAND);p.setShiftKeyDown(false);check(AdvancedToolModes.get(stack)==(mode+1)%3,"native shift-use cycles mode");}
 var recipe=dev.eugheist.tc4modern.InfusionItemRecipes.all().stream().filter(r->r.key().equals("ICHOR_PICK_GEM")).findFirst().orElseThrow();var parts=recipe.componentStacks();check(parts.size()==12&&parts.stream().noneMatch(net.minecraft.world.item.ItemStack::isEmpty)&&parts.get(2).is(FocusResearch.item("elemental_pickaxe"))&&parts.get(10).is(FocusResearch.item("elemental_pickaxe"))&&parts.get(5).is(FocusResearch.item("cinnabar_cluster")),"original resolved twelve components");check(dev.eugheist.tc4modern.InfusionItemRecipes.match(parts,new net.minecraft.world.item.ItemStack(KamiTools.PICK.get()),java.util.Set.of("ICHOR_PICK_GEM"))==recipe,"native infusion accepted");check(recipe.instability()==15&&recipe.aspects().getAmount(thaumcraft.api.aspects.Aspect.MINE)==64&&recipe.aspects().getAmount(thaumcraft.api.aspects.Aspect.FIRE)==50,"original costs");check(AwakenedPick.ITEM.get().getDestroySpeed(stack,net.minecraft.world.level.block.Blocks.BEDROCK.defaultBlockState())==Float.MAX_VALUE,"original bedrock tool speed; portal integration pending");System.out.println("TT AWAKENED PICK AUDIT: ALL PASS (real native single/25block/depth11 mining,shift-use cycle,12part infusion/research,costs)");
 }finally{saved.forEach((at,state)->level.setBlock(at,state,2));p.discard();}
 }
}
